/* system24 v2.1.0 by refact0r — vendored: midnight.css + system24.css, fonts kept as @import */
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:ital,wght@0,300;0,400;0,500;1,300;1,400;1,500&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Figtree:ital,wght@0,300;0,400;0,500;0,600;0,700;0,800;0,900;1,300;1,400;1,500;1,600;1,700;1,800;1,900&display=swap');
/* main.css */

:root {
    container-name: root;

    --custom-guild-list-padding: 12px;
    --panel-backdrop-filter: none;
}

body {
    container-name: body;

    /* font, change to '' for default discord font */
    --font: 'figtree';
    --code-font: '';

    /* sizes */
    --gap: 12px; /* spacing between panels */
    --divider-thickness: 4px; /* thickness of unread messages divider and highlighted message borders */
    --border-thickness: 1px; /* thickness of borders around main panels. DOES NOT AFFECT OTHER BORDERS */
    --custom-guild-list-width: calc(var(--guildbar-avatar-size) + var(--custom-guild-list-padding) * 2 + var(--border-thickness) * 2);

    --border-hover-transition: 0.2s ease;
    --elevation-low: none;
    --elevation-medium: none;
    --elevation-high: none;
}

/* panel separation */
.container_rhYbEd > .toolbar_rhYbEd /* server boosts titlebar */,
.container_rhYbEd > .contentContainer_rhYbEd /* server boosts tab */,
.guilds_pog62O /* server list */,
