/* unrounding.css */
@property --unrounding {
    syntax: 'off | on';
    inherits: false;
    initial-value: on;
}

@property --round-pfp {
    syntax: 'off | on';
    inherits: false;
    initial-value: off;
}

@property --remove-pfp-decor {
    syntax: 'off | on';
    inherits: false;
    initial-value: off;
}

@container body style(--unrounding: on) {
    *::before,
