    /* Exclude avatar wrapper so that --round-pfp has full control */
    *:not(.wrapper_XpIUHy):not(.container_pfDcF-):not(.avatar_2i8Bfm):not(.replyAvatar_2i8Bfm) {
        border-radius: 0 !important;
        --radius-none: 0px !important;
        --radius-xs: 0px !important;
        --radius-sm: 0px !important;
        --radius-md: 0px !important;
        --radius-lg: 0px !important;
        --radius-xl: 0px !important;
        --radius-xxl: 0px !important;
        --radius-round: 0px !important;
    }

    /* Server icons */
    .svg_hqZPsU > mask {
        display: none;
    }

    .svg_SZ8p4i.imageContainer_1AI0dL > foreignObject {
        mask: none;
    }

    .wrapper_XpIUHy,
    .container_pfDcF- {
        --online-2: #43a25a;
        --dnd-2: #d83a41;
        --idle-2: #ca9654;
        --offline-2: #82838b;
