    .wrapper_XpIUHy:has(> .svg_XpIUHy > g > rect)::after,
    .container_pfDcF-:has(> .mask_PlwcO5 .status_PlwcO5)::after {
        content: '';
        display: block;
        position: absolute;
        height: 8px;
        width: 8px;
